begin;
alter table public.plop_orders add column subtotal bigint not null default 0,add column discount bigint not null default 0,add column coupon_code text,add column attribution jsonb not null default '{}',add column session_id uuid,add column customer_id uuid,add column is_test boolean not null default false;
create table public.plop_contacts(id uuid primary key default gen_random_uuid(),name text not null,phone text not null unique,email text,career text,locality text,graduation_date date,source text not null default 'directo',marketing_consent boolean not null default false,consent_at timestamptz,stage text not null default 'consulta',unsubscribe_key uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.plop_orders add constraint plop_orders_customer_fk foreign key(customer_id) references public.plop_contacts(id);
create table public.plop_coupons(code text primary key check(code ~ '^[A-Z0-9_-]{3,24}$'),kind text not null check(kind in ('percent','amount')),value integer not null check(value>0),starts_at timestamptz not null,ends_at timestamptz not null,limit_uses integer not null check(limit_uses>0),uses integer not null default 0,product_id text references public.plop_catalog(id),active boolean not null default true,created_at timestamptz not null default now(),check(ends_at>starts_at),check(kind<>'percent' or value<=90));
create table public.plop_campaigns(id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9-]{3,64}$'),name text not null,title text not null,description text not null default '',source text not null default 'instagram',medium text not null default 'social',products jsonb not null default '[]',coupon text references public.plop_coupons(code),active boolean not null default true,created_at timestamptz not null default now());
create table public.plop_ad_spend(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.plop_campaigns(id),date date not null,amount bigint not null check(amount>=0),reach bigint,clicks bigint,created_at timestamptz not null default now());
create table public.plop_events(id uuid primary key,session_id uuid not null,event text not null check(event in ('page_view','product_view','select_product','add_to_cart','remove_from_cart','checkout_started','order_sent','receipt_uploaded','whatsapp_click','instagram_click','email_click')),product_id text references public.plop_catalog(id),source text not null default 'directo',campaign text not null default '',device text not null check(device in ('mobile','tablet','desktop')),amount bigint,occurred_at timestamptz not null default now());
create index plop_events_date on public.plop_events(occurred_at,event);create index plop_events_session on public.plop_events(session_id,event);create index plop_spend_campaign_date on public.plop_ad_spend(campaign_id,date);
create table public.plop_reviews(id uuid primary key default gen_random_uuid(),pedido_id uuid not null unique references public.plop_orders(id),display_name text not null,text text not null check(char_length(text) between 5 and 600),rating integer not null check(rating between 1 and 5),consent boolean not null check(consent),photo_path text,public_photo_url text,status text not null default 'pending' check(status in ('pending','approved','rejected')),moderated_by uuid,created_at timestamptz not null default now());
create table public.plop_meta_jobs(event_id text primary key,payload jsonb not null,status text not null default 'pending',attempts integer not null default 0,created_at timestamptz not null default now(),last_error text);
create table public.plop_marketing_jobs(id uuid primary key default gen_random_uuid(),contact_id uuid not null references public.plop_contacts(id),kind text not null,subject text not null,message text not null,dedupe_key text not null unique,status text not null default 'pending',created_at timestamptz not null default now(),sent_at timestamptz,last_error text);
create or replace function plop_private.coupon_discount(p_code text,p_items jsonb,p_subtotal bigint) returns bigint language plpgsql security definer set search_path='' as $$declare c public.plop_coupons%rowtype;eligible bigint;v bigint;begin
 if coalesce(p_code,'')='' then return 0;end if;select * into c from public.plop_coupons where code=upper(p_code) for update;if not found or not c.active or now()<c.starts_at or now()>c.ends_at or c.uses>=c.limit_uses then raise exception 'invalid_coupon';end if;
 select coalesce(sum((i->>'quantity')::bigint*(i->>'price')::bigint),0) into eligible from jsonb_array_elements(p_items) i where c.product_id is null or i->>'productId'=c.product_id;
 if eligible=0 then raise exception 'coupon_product_mismatch';end if;v:=case when c.kind='percent' then (eligible*c.value)/100 else least(eligible,c.value) end;if v>=p_subtotal then raise exception 'coupon_total_zero';end if;return v;end;$$;
create or replace function plop_private.marketing_after_order() returns trigger language plpgsql security definer set search_path='' as $$begin
 if TG_OP='INSERT' then
  if new.coupon_code is not null then update public.plop_coupons set uses=uses+1 where code=new.coupon_code;end if;
  if coalesce(new.contact->>'email','')<>'' then insert into public.plop_notifications(pedido_id,event,dedupe_key) values(new.id,'confirmacion_cliente','cliente:'||new.id) on conflict do nothing;end if;
 end if;
 if TG_OP='UPDATE' and new.status<>old.status and new.status='entregado' then insert into public.plop_notifications(pedido_id,event,dedupe_key) values(new.id,'resena','resena:'||new.id) on conflict do nothing;end if;
 if (TG_OP='UPDATE' and old.verified_paid<old.deposit and new.verified_paid>=new.deposit) and coalesce((new.attribution->>'adsConsent')::boolean,false) then insert into public.plop_meta_jobs(event_id,payload) values(new.id||':deposit',jsonb_build_object('event_name','Purchase','event_id',new.id||':deposit','event_time',extract(epoch from now())::bigint,'action_source','website','event_source_url','https://plop-recibidas-tienda.abuzzflea1.chatgpt.site/','user_data',jsonb_build_object('fbp',new.attribution->>'fbp','fbc',new.attribution->>'fbc'),'custom_data',jsonb_build_object('currency','ARS','value',new.deposit))) on conflict do nothing;end if;
 return new;end;$$;
create trigger plop_marketing_order after insert or update on public.plop_orders for each row execute function plop_private.marketing_after_order();
alter table public.plop_contacts enable row level security;alter table public.plop_coupons enable row level security;alter table public.plop_campaigns enable row level security;alter table public.plop_ad_spend enable row level security;alter table public.plop_events enable row level security;alter table public.plop_reviews enable row level security;alter table public.plop_meta_jobs enable row level security;alter table public.plop_marketing_jobs enable row level security;
create policy contacts_staff on public.plop_contacts for all to authenticated using(plop_private.is_staff()) with check(plop_private.is_staff());
create policy coupons_staff on public.plop_coupons for all to authenticated using(plop_private.is_staff()) with check(plop_private.is_staff());
create policy campaigns_read on public.plop_campaigns for select to anon,authenticated using(active);create policy campaigns_staff on public.plop_campaigns for all to authenticated using(plop_private.is_staff()) with check(plop_private.is_staff());
create policy spend_staff on public.plop_ad_spend for all to authenticated using(plop_private.is_staff()) with check(plop_private.is_staff());
create policy events_staff on public.plop_events for select to authenticated using(plop_private.is_staff());
create policy reviews_public on public.plop_reviews for select to anon,authenticated using(status='approved');create policy reviews_staff on public.plop_reviews for all to authenticated using(plop_private.is_staff()) with check(plop_private.is_staff());
revoke all on public.plop_contacts,public.plop_coupons,public.plop_campaigns,public.plop_ad_spend,public.plop_events,public.plop_reviews,public.plop_meta_jobs,public.plop_marketing_jobs from anon,authenticated;
grant select,insert,update on public.plop_contacts,public.plop_coupons,public.plop_ad_spend to authenticated;
grant select,insert,update on public.plop_campaigns,public.plop_reviews to authenticated;grant select on public.plop_campaigns,public.plop_reviews to anon;grant select on public.plop_events to authenticated;
grant all on public.plop_contacts,public.plop_coupons,public.plop_campaigns,public.plop_ad_spend,public.plop_events,public.plop_reviews,public.plop_meta_jobs,public.plop_marketing_jobs to service_role;
create or replace view public.plop_looker_orders with(security_invoker=true) as select id,created_at,contact->>'date' as graduation_date,status,subtotal,discount,total,deposit,verified_paid,attribution->>'source' as source,attribution->>'utm_campaign' as campaign,contact->>'locality' as locality,items->0->'custom'->>'career' as career,coupon_code from public.plop_orders where not is_test;
create or replace view public.plop_looker_payments with(security_invoker=true) as select p.id,p.pedido_id,p.tipo,p.monto_esperado,p.monto_recibido,p.diferencia,p.medio,p.fecha_pago,p.estado,p.created_at from public.pagos p join public.plop_orders o on o.id=p.pedido_id where not o.is_test;
create or replace view public.plop_looker_events with(security_invoker=true) as select * from public.plop_events;
revoke all on public.plop_looker_orders,public.plop_looker_payments,public.plop_looker_events from anon;grant select on public.plop_looker_orders,public.plop_looker_payments,public.plop_looker_events to authenticated,service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('plop-review-private','plop-review-private',false,5242880,array['image/jpeg','image/png','image/webp']),('plop-review-approved','plop-review-approved',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy plop_review_staff_read on storage.objects for select to authenticated using(bucket_id='plop-review-private' and plop_private.is_staff());
revoke all on all functions in schema plop_private from public,anon;
create or replace function plop_private.validate_order() returns trigger language plpgsql security definer set search_path='' as $$
declare item jsonb;product public.plop_catalog%rowtype;q integer;unit bigint;computed bigint:=0;result jsonb:='[]';day date;cid uuid;begin
 if TG_OP='INSERT' then
  if new.owner_id<>auth.uid() and coalesce(current_setting('request.jwt.claims',true)::jsonb->>'role','')<>'service_role' then raise exception 'invalid_owner';end if;
  if jsonb_typeof(new.items)<>'array' or jsonb_array_length(new.items) not between 1 and 30 then raise exception 'invalid_items';end if;
  if coalesce(length(trim(new.contact->>'name')),0) not between 2 and 100 or coalesce(new.contact->>'phone','') !~ '^\+549[0-9]{10}$' or coalesce(length(trim(new.contact->>'locality')),0) not between 2 and 100 or coalesce(new.contact->>'consent','')<>'true' then raise exception 'invalid_contact';end if;
  if coalesce(new.contact->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'invalid_date';end if;day:=(new.contact->>'date')::date;if day<(now() at time zone 'America/Argentina/Cordoba')::date then raise exception 'invalid_date';end if;
  if (select count(*) from public.plop_orders where owner_id=new.owner_id and created_at>now()-interval '1 hour')>=5 then raise exception 'too_many_orders';end if;
  if (select count(*) from public.plop_orders where regexp_replace(contact->>'phone','[^0-9]','','g')=regexp_replace(new.contact->>'phone','[^0-9]','','g') and created_at>now()-interval '1 day')>=5 then raise exception 'too_many_orders';end if;
  for item in select value from jsonb_array_elements(new.items) loop
   select * into product from public.plop_catalog where id=item->>'productId' and available; if not found then raise exception 'unavailable_product';end if;
   q:=(item->>'quantity')::integer;if q not between 1 and 20 then raise exception 'invalid_quantity';end if;
   unit:=product.price;if coalesce((product.data->>'frameOption')::boolean,false) and item->'custom'->>'frame'<>'Rectangular' then unit:=unit+3000;end if;
   computed:=computed+unit*q;result:=result||jsonb_build_array(jsonb_build_object('productId',product.id,'name',product.data->>'name','quantity',q,'price',unit,'custom',item->'custom','includes',product.data->>'includes'));
  end loop;
  if computed>5000000 then raise exception 'order_too_large';end if;new.subtotal:=computed;new.coupon_code:=nullif(upper(coalesce(new.coupon_code,'')),'');new.discount:=plop_private.coupon_discount(new.coupon_code,result,computed);computed:=computed-new.discount;if new.total<>computed then raise exception 'cart_price_changed';end if;new.total:=computed;new.items:=result;insert into public.plop_contacts(name,phone,email,career,locality,graduation_date,source,marketing_consent,consent_at,stage) values(new.contact->>'name',new.contact->>'phone',nullif(new.contact->>'email',''),new.items->0->'custom'->>'career',new.contact->>'locality',(new.contact->>'date')::date,coalesce(new.attribution->>'source','directo'),coalesce((new.contact->>'marketingConsent')::boolean,false),now(),'cliente') on conflict(phone) do update set name=excluded.name,email=coalesce(excluded.email,plop_contacts.email),career=excluded.career,locality=excluded.locality,graduation_date=excluded.graduation_date,marketing_consent=excluded.marketing_consent,consent_at=now(),stage='cliente',updated_at=now() returning id into cid;new.customer_id:=cid;new.status:='nuevo';new.verified_paid:=0;new.reserved_at:=null;new.design_approved:=false;new.last_actor:=new.owner_id;
 else
  if new.total<>old.total or new.items<>old.items or new.owner_id<>old.owner_id or new.request_key<>old.request_key or new.subtotal<>old.subtotal or new.discount<>old.discount or new.coupon_code is distinct from old.coupon_code then raise exception 'immutable_order';end if;
  if new.verified_paid>=((new.total+1)/2) and new.status<>'cancelado' then new.reserved_at:=coalesce(new.reserved_at,now());else new.reserved_at:=null;end if;
  if new.status in ('sena_recibida','en_produccion','entregado') and new.verified_paid<((new.total+1)/2) then raise exception 'deposit_required';end if;
  if new.status='en_produccion' and not new.design_approved then raise exception 'design_required';end if;
  if new.status='entregado' and new.verified_paid<new.total then raise exception 'balance_required';end if;
 end if;if auth.uid() is not null then new.last_actor:=auth.uid();end if;new.updated_at:=now();return new;
end;$$;

commit;
